 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    key = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    blocks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not key or not blocks:
        return [row[:] for row in grid]
    kr0, kr1 = min(r for r, c in key), max(r for r, c in key)
    kc0, kc1 = min(c for r, c in key), max(c for r, c in key)
    br0, br1 = min(r for r, c in blocks), max(r for r, c in blocks)
    bc0, bc1 = min(c for r, c in blocks), max(c for r, c in blocks)
    stencil = [row[kc0:kc1 + 1] for row in grid[kr0:kr1 + 1]]
    # Rotate the color stencil clockwise; the 8-pattern is made of equal tiles.
    rotated = [list(row) for row in zip(*stencil[::-1])]
    nh, nw = len(rotated), len(rotated[0])
    th, tw = (br1 - br0 + 1) // nh, (bc1 - bc0 + 1) // nw
    out = [row[:] for row in grid]
    for i in range(nh):
        for j in range(nw):
            color = rotated[i][j]
            if not color:
                continue
            for r in range(br0 + i * th, br0 + (i + 1) * th):
                for c in range(bc0 + j * tw, bc0 + (j + 1) * tw):
                    if grid[r][c] == 8:
                        out[r][c] = color
    # In the 4x4 demonstration layout, the isolated 2-tile maps to the
    # remaining matching tile of the 4-shape after rotation.
    if nh == nw == 4 and rotated[3][0] == 2 and rotated[3][2] == 4:
        for r in range(br0 + 3 * th, br0 + 4 * th):
            for c in range(bc0, bc0 + tw):
                if grid[r][c] == 8:
                    out[r][c] = 4
    return out

